/**
 * Parses and extracts demo token with the following priority:
 * 1. Read ?wz_token=TOKEN from window.location.search
 * 2. Check /demo/TOKEN from window.location.pathname
 * 3. Return null if neither exists
 */
export declare function extractDemoToken(customSearchOrPathname?: string, customPathname?: string): string | null;
/**
 * Checks if user is browsing from a mobile device
 */
export declare function isMobileDevice(): boolean;
